rollback;
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();image uuid;post uuid;root_comment uuid;reply uuid;box jsonb;stats jsonb;group1 uuid;n integer;
begin
 insert into auth.users(id,raw_user_meta_data) values(a,'{}'),(b,'{}'),(c,'{}');
 update public.profiles set first_name='Test',last_name='Member' where id in(a,b,c);
 insert into public.humor_images(user_id,status,image_width,image_height) values(a,'ready',600,800) returning id into image;
 insert into public.humor_captions(image_id,content) values(image,'Rollback-only member test') returning id into post;
 insert into public.humor_votes(user_id,caption_id,value) values(b,post,1),(c,post,1),(a,post,1);
 if (select count(*) from public.notifications where recipient_id=a)<>2 then raise exception 'Self Ha notified or other Ha missing';end if;
 if (public.humor_notification_summary(a)->>'unreadCount')::int<>1 then raise exception 'Ha group count failed';end if;
 box:=public.humor_notifications_page(a,false);
 if (box->'items'->0->>'actorCount')::int<>2 then raise exception 'Ha actor grouping failed';end if;
 group1:=(box->'items'->0->>'id')::uuid;
 delete from public.humor_votes where user_id=c and caption_id=post;
 if (public.humor_notifications_page(a,false)->'items'->0->>'actorCount')::int<>1 then raise exception 'Un-Ha did not remove unread event';end if;
 insert into public.humor_votes(user_id,caption_id,value) values(c,post,1);
 update public.humor_votes set value=1 where user_id=c and caption_id=post;
 if (select count(*) from public.notifications where recipient_id=a)<>2 then raise exception 'Repeated Ha duplicated event';end if;
 box:=public.humor_notifications_page(a,true);
 if (box->'summary'->>'unreadCount')::int<>0 or not (box->'items'->0->>'wasUnread')::boolean then raise exception 'Open read snapshot failed';end if;
 delete from public.humor_votes where user_id=c and caption_id=post;
 if (select count(*) from public.notifications where recipient_id=a)<>2 then raise exception 'Read Ha history incorrectly erased';end if;
 insert into public.humor_votes(user_id,caption_id,value) values(c,post,1);
 if (select count(distinct batch_id) from public.notifications where recipient_id=a)<>2 then raise exception 'New unread batch after read failed';end if;
 insert into public.humor_comments(caption_id,user_id,content) values(post,a,'Own comment') returning id into root_comment;
 if exists(select 1 from public.notifications where comment_id=root_comment) then raise exception 'Self comment notified';end if;
 insert into public.humor_comments(caption_id,user_id,content,reply_to_id) values(post,b,'Reply',root_comment) returning id into reply;
 if (select count(*) from public.notifications where comment_id=reply)<>1 or not exists(select 1 from public.notifications where comment_id=reply and type='reply' and recipient_id=a) then raise exception 'Reply precedence failed';end if;
 insert into public.humor_comments(caption_id,user_id,content) values(post,c,'Other root') returning id into root_comment;
 insert into public.humor_comments(caption_id,user_id,content,reply_to_id) values(post,b,'Two recipients',root_comment) returning id into reply;
 if (select count(*) from public.notifications where comment_id=reply)<>2 then raise exception 'Distinct reply recipients missing';end if;
 perform public.delete_humor_comment(root_comment,c);
 if exists(select 1 from public.notifications where reply_to_comment_id=root_comment) then raise exception 'Deleted parent notifications remain';end if;
 if (public.humor_comment_row(reply,a)->'replyTo'->>'authorName')<>'deleted' then raise exception 'Reply tombstone failed';end if;
 stats:=public.humor_profile_summary(a,b);
 if (stats->>'postCount')::int<>1 or (stats->>'haReceived')::int<>3 or stats->>'onboardedAt' is not null then raise exception 'Profile counts or private state failed';end if;
 perform public.humor_save_profile(a,' New Name ',null);
 if public.humor_author(a)->>'name'<>'New Name' or public.humor_comment_row(reply,a)->'author'->>'id'<>b::text then raise exception 'Author projection failed';end if;
 if (public.humor_profile_posts(a,b)->'posts'->0->'author'->>'name')<>'New Name' then raise exception 'Public post author not refreshed';end if;
 -- Private notifications cannot be read or changed by another member.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','app_metadata',jsonb_build_object('providers',jsonb_build_array('google')),'amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',1000)))::text,true);
 execute 'set local role authenticated';
 select count(*) into n from public.notifications where recipient_id=a;
 if n<>0 then raise exception 'Cross-user notification read';end if;
 if has_column_privilege('authenticated','public.profiles','is_official','update') or has_column_privilege('authenticated','public.profiles','onboarded_at','update') or has_function_privilege('authenticated','public.humor_notify(uuid,uuid,text,uuid,uuid,uuid)','execute') then raise exception 'Privileged writes exposed';end if;
 execute 'reset role';
 update public.humor_captions set deleted_at=now() where id=post;
 if exists(select 1 from public.notifications where post_id=post) then raise exception 'Post notifications not cleaned';end if;
 if (select count(*) from public.humor_captions where source='seed')<>0 then raise exception 'Unexpected production seed data';end if;
end $$;
rollback;
select 'PASS: notification grouping/read/un-Ha/reply/delete lifecycle, profile statistics/name projection, own-only RLS and server-only flags. All fixtures rolled back.' as result;
